<?php
$sessionMatricule=$_SESSION['user']['matricule']??'Utilisateur';$sessionNom=trim($_SESSION['user']['nom_utilisateur']??'')?:$sessionMatricule;$sessionProfil=$_SESSION['user']['profil']??'';$role=$_SESSION['user']['role']??'';
$labels=['ACTIF'=>'Actif','SUSPENDU'=>'Suspendu','LICENCIE'=>'Licencié'];$counts=array_fill_keys(array_keys($labels),0);foreach($travailleurs as $t)if(isset($counts[$t['statut']]))$counts[$t['statut']]++;
?>
<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Travailleurs - <?= APP_NAME ?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Outfit:wght@600;700&display=swap" rel="stylesheet"><link href="<?= BASE_URL ?>/assets/css/dashboard.css" rel="stylesheet"><link href="<?= BASE_URL ?>/assets/css/users.css" rel="stylesheet"><link href="<?= BASE_URL ?>/assets/css/profile.css" rel="stylesheet"><link href="<?= BASE_URL ?>/assets/css/workers.css" rel="stylesheet"><link href="<?= BASE_URL ?>/assets/css/theme.css" rel="stylesheet"><script src="<?= BASE_URL ?>/assets/js/theme-mode.js"></script></head><body>
<div class="dashboard-shell"><div class="mobile-overlay" id="mobile-overlay" onclick="toggleSidebar()"></div><aside class="dashboard-sidebar" id="dashboard-sidebar"><a class="brand" href="<?= BASE_URL ?>/dashboard"><span class="brand-icon"><i class="bi bi-truck"></i></span><span><strong>MWIRA Trans</strong><small>Gestion de transport</small></span></a><nav class="dashboard-nav"><span class="nav-heading">Vue générale</span><a href="<?= BASE_URL ?>/dashboard"><i class="bi bi-grid-1x2"></i> Tableau de bord</a><span class="nav-heading">Exploitation</span><a href="<?= BASE_URL ?>/vehicules"><i class="bi bi-truck"></i> Véhicules</a><a class="active" href="<?= BASE_URL ?>/travailleurs"><i class="bi bi-people"></i> Travailleurs</a><a href="<?= BASE_URL ?>/affectations"><i class="bi bi-arrow-left-right"></i> Affectations</a><span class="nav-heading">Finances</span><a href="<?= BASE_URL ?>/recettes"><i class="bi bi-graph-up-arrow"></i> Recettes</a><a href="<?= BASE_URL ?>/depenses"><i class="bi bi-wallet2"></i> Dépenses</a><a href="<?= BASE_URL ?>/caisse"><i class="bi bi-bank"></i> Caisse</a><a href="<?= BASE_URL ?>/rapports"><i class="bi bi-bar-chart"></i> Rapports</a><?php if($role==='ADMIN'):?><span class="nav-heading">Administration</span><a href="<?= BASE_URL ?>/utilisateurs"><i class="bi bi-person-gear"></i> Utilisateurs</a><a href="<?= BASE_URL ?>/audit"><i class="bi bi-journal-text"></i> Audit</a><?php endif;?></nav><div class="sidebar-user"><span class="avatar"><?php if($sessionProfil):?><img src="<?= BASE_URL.'/'.htmlspecialchars($sessionProfil) ?>" alt="Profil"><?php else:?><?= htmlspecialchars(strtoupper(substr($sessionNom,0,2))) ?><?php endif;?></span><span class="user-copy"><strong><?= htmlspecialchars($sessionNom) ?></strong><small><?= htmlspecialchars($sessionMatricule) ?></small></span><a class="logout" href="<?= BASE_URL ?>/logout"><i class="bi bi-box-arrow-right"></i></a></div></aside>
<main class="dashboard-main"><header class="dashboard-topbar"><button class="menu-button" onclick="toggleSidebar()"><i class="bi bi-list"></i></button><div><h1>Gestion des travailleurs</h1><p>Personnel et situation professionnelle</p></div><div class="topbar-date"><i class="bi bi-people"></i> <?= count($travailleurs) ?> travailleur(s)</div></header><div class="users-content"><div class="breadcrumbs"><a href="<?= BASE_URL ?>/dashboard">Tableau de bord</a><i class="bi bi-chevron-right"></i><span>Travailleurs</span></div><section class="users-heading"><div><h2>Personnel</h2><p>Gérez les informations et les photos de vos travailleurs.</p></div><button class="add-button" onclick="openWorkerModal()"><i class="bi bi-person-plus"></i> Ajouter un travailleur</button></section>
<section class="worker-stats"><article><i class="bi bi-people"></i><span><strong><?= count($travailleurs) ?></strong><small>Total</small></span></article><article><i class="bi bi-person-check"></i><span><strong><?= $counts['ACTIF'] ?></strong><small>Actifs</small></span></article><article><i class="bi bi-person-dash"></i><span><strong><?= $counts['SUSPENDU'] ?></strong><small>Suspendus</small></span></article><article><i class="bi bi-person-x"></i><span><strong><?= $counts['LICENCIE'] ?></strong><small>Licenciés</small></span></article></section>
<section class="users-toolbar worker-toolbar"><label class="search-field"><i class="bi bi-search"></i><input id="worker-search" type="search" placeholder="Nom, matricule, téléphone…" oninput="filterWorkers()"></label><select id="worker-status" onchange="filterWorkers()"><option value="">Tous les statuts</option><?php foreach($labels as $value=>$label):?><option value="<?= $value ?>"><?= $label ?></option><?php endforeach;?></select><span id="worker-count"><?= count($travailleurs) ?> travailleur(s)</span></section>
<section class="users-table-card"><div class="users-table-scroll"><table class="workers-table"><thead><tr><th>Travailleur</th><th>Coordonnées</th><th>Sexe</th><th>Embauche</th><th>Statut</th><th></th></tr></thead><tbody id="workers-body"><?php if(!$travailleurs):?><tr><td colspan="6" class="users-empty"><i class="bi bi-people"></i><strong>Aucun travailleur</strong><span>Ajoutez votre premier travailleur.</span></td></tr><?php endif;?>
<?php foreach($travailleurs as $t):$full=trim(implode(' ',array_filter([$t['nom'],$t['postnom'],$t['prenom']])));$json=htmlspecialchars(json_encode($t),ENT_QUOTES,'UTF-8');$search=strtolower($full.' '.$t['matricule'].' '.$t['telephone'].' '.$t['email']);?><tr data-search="<?= htmlspecialchars($search) ?>" data-status="<?= $t['statut'] ?>"><td><div class="identity"><span><?php if($t['profil']):?><img src="<?= BASE_URL.'/'.htmlspecialchars($t['profil']) ?>" alt="Profil"><?php else:?><?= htmlspecialchars(strtoupper(substr($full,0,2))) ?><?php endif;?></span><div><strong><?= htmlspecialchars($full) ?></strong><small><?= htmlspecialchars($t['matricule']) ?></small></div></div></td><td><?= htmlspecialchars($t['telephone']?:'—') ?><small class="worker-muted"><?= htmlspecialchars($t['email']?:'Email non renseigné') ?></small></td><td><?= $t['sexe']==='M'?'Masculin':($t['sexe']==='F'?'Féminin':'—') ?></td><td><?= $t['date_embauche']?date('d/m/Y',strtotime($t['date_embauche'])):'—' ?></td><td><span class="worker-status status-<?= strtolower($t['statut']) ?>"><?= $labels[$t['statut']]??$t['statut'] ?></span></td><td><div class="row-actions"><button onclick="openWorkerModal(<?= $json ?>)"><i class="bi bi-pencil"></i></button><button class="danger" onclick="openDeleteWorker(<?= (int)$t['id'] ?>,'<?= htmlspecialchars($full,ENT_QUOTES) ?>')"><i class="bi bi-trash3"></i></button></div></td></tr><?php endforeach;?></tbody></table></div></section></div><footer class="dashboard-footer">© <?= date('Y') ?> MWIRA Trans <span>Gestion du personnel</span></footer></main></div>
<?php if($message):?><div class="users-toast <?= $messageType==='error'?'error':'' ?>"><i class="bi bi-<?= $messageType==='error'?'exclamation-circle':'check-circle' ?>"></i><?= htmlspecialchars($message) ?></div><?php endif;?>
<div class="users-modal-overlay" id="worker-modal"><div class="users-modal worker-modal"><div class="modal-title"><div><h3 id="worker-modal-title">Ajouter un travailleur</h3><p>Identité et informations professionnelles</p></div><button onclick="closeModal('worker-modal')">&times;</button></div><form method="POST" enctype="multipart/form-data" action="<?= BASE_URL ?>/travailleurs"><input type="hidden" name="action" id="worker-action" value="create"><input type="hidden" name="id" id="worker-id"><label class="profile-upload"><span class="profile-preview" id="worker-preview"><i class="bi bi-camera"></i></span><span>Photo du travailleur<small>JPG, PNG ou WEBP · 2 Mo maximum</small></span><input type="file" name="profil" id="worker-profile" accept="image/jpeg,image/png,image/webp" onchange="previewWorker(this)"></label><div class="worker-form-grid"><label>Nom *<input name="nom" id="nom" required maxlength="100"></label><label>Postnom<input name="postnom" id="postnom" maxlength="100"></label><label>Prénom<input name="prenom" id="prenom" maxlength="100"></label><label>Sexe<select name="sexe" id="sexe"><option value="">Non précisé</option><option value="M">Masculin</option><option value="F">Féminin</option></select></label><label>Téléphone<input name="telephone" id="telephone" maxlength="30"></label><label>Email<input type="email" name="email" id="email" maxlength="150"></label><label>Date d’embauche<input type="date" name="date_embauche" id="date_embauche"></label><label>Statut<select name="statut" id="statut"><?php foreach($labels as $value=>$label):?><option value="<?= $value ?>"><?= $label ?></option><?php endforeach;?></select></label><label class="full-field">Adresse<input name="adresse" id="adresse" maxlength="255"></label></div><div class="modal-buttons"><button type="button" class="cancel" onclick="closeModal('worker-modal')">Annuler</button><button type="submit" class="save"><i class="bi bi-check-lg"></i> Enregistrer</button></div></form></div></div>
<div class="users-modal-overlay" id="delete-worker-modal"><div class="users-modal confirm-modal"><span class="warning-icon"><i class="bi bi-exclamation-triangle"></i></span><h3>Supprimer ce travailleur ?</h3><p><strong id="delete-worker-name"></strong> sera retiré de la liste.</p><form method="POST" action="<?= BASE_URL ?>/travailleurs"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" id="delete-worker-id"><div class="modal-buttons"><button type="button" class="cancel" onclick="closeModal('delete-worker-modal')">Annuler</button><button class="delete-confirm">Supprimer</button></div></form></div></div>
<script>
function openWorkerModal(w=null){const f=['nom','postnom','prenom','sexe','telephone','email','date_embauche','statut','adresse'];document.getElementById('worker-action').value=w?'update':'create';document.getElementById('worker-id').value=w?.id||'';f.forEach(x=>document.getElementById(x).value=w?.[x]??(x==='statut'?'ACTIF':''));document.getElementById('worker-profile').value='';document.getElementById('worker-preview').innerHTML=w?.profil?`<img src="<?= BASE_URL ?>/${w.profil}" alt="Profil">`:'<i class="bi bi-camera"></i>';document.getElementById('worker-modal-title').textContent=w?'Modifier le travailleur':'Ajouter un travailleur';openModal('worker-modal')}function previewWorker(i){if(!i.files[0])return;const r=new FileReader();r.onload=e=>document.getElementById('worker-preview').innerHTML=`<img src="${e.target.result}" alt="Aperçu">`;r.readAsDataURL(i.files[0])}function filterWorkers(){const q=document.getElementById('worker-search').value.toLowerCase().trim(),s=document.getElementById('worker-status').value;let n=0;document.querySelectorAll('#workers-body tr[data-search]').forEach(r=>{const show=(!q||r.dataset.search.includes(q))&&(!s||r.dataset.status===s);r.style.display=show?'':'none';if(show)n++});document.getElementById('worker-count').textContent=n+' travailleur(s)'}function openDeleteWorker(id,n){document.getElementById('delete-worker-id').value=id;document.getElementById('delete-worker-name').textContent=n;openModal('delete-worker-modal')}function openModal(id){document.getElementById(id).classList.add('show')}function closeModal(id){document.getElementById(id).classList.remove('show')}function toggleSidebar(){document.getElementById('dashboard-sidebar').classList.toggle('open');document.getElementById('mobile-overlay').classList.toggle('show')}setTimeout(()=>document.querySelector('.users-toast')?.remove(),4000);
</script></body></html>
